from pwn import *

def collatz_sequence(x):
    while x != 1:
        if x % 2 == 0:  # Even
            x //= 2
        else:  # Odd
            x = x * 3 + 1
    return x

# Test the function locally
if __name__ == "__main__":
    test_values = [10, 15, 27, 50, 1]
    for val in test_values:
        print(f"Input: {val}, Result: ", collatz_sequence(val))

