from pwn import *
import re

def send_input(payload):
    # Execute the binary and provide input
    p = process("/home/ctfplayer/ctf_files/counting")
    p.sendline(payload)
    result = p.recvall(timeout=2).decode(errors="ignore")
    p.close()
    return result

def collatz_steps(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

def trial_input():
    for number in range(1, 10000):
        transformed_number = collatz_steps(number)
        payload = f"{number}"
        result = send_input(payload)

        if "flag{" in result:
            print(result)
            return
        else:
            print(f"Tested input {number} -> No Flag")

if __name__ == "__main__":
    trial_input()

